using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    //  CalculateTotal – inline data with [DataRow]
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00, 10, 0.10, 0.00, DisplayName = "Zero unit price")]
    [DataRow(99.99, 0, 0.05, 0.00, DisplayName = "Zero quantity")]
    [DataRow(10.00, 1, 1.0, 20.00, DisplayName = "100% tax rate")]
    public void CalculateTotal_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    //  CalculateTotal – invalid inputs
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
    [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below zero")]
    [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInput_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – complex scenarios with [DynamicData]
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> DiscountTestCases
    {
        get
        {
            yield return new object[] { 100.00m, 0m, 100.00m, "No discount" };
            yield return new object[] { 100.00m, 10m, 90.00m, "10% off" };
            yield return new object[] { 100.00m, 50m, 50.00m, "50% off" };
            yield return new object[] { 100.00m, 100m, 0.00m, "100% off (free)" };
            yield return new object[] { 49.99m, 25m, 37.4925m, "Fractional result" };
            yield return new object[] { 0.00m, 50m, 0.00m, "Zero price" };
            yield return new object[] { 1000.00m, 0.5m, 995.00m, "Half-percent discount" };
        }
    }

    [TestMethod]
    [DynamicData(nameof(DiscountTestCases))]
    public void ApplyDiscount_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for scenario: {scenario}");
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – invalid discount percentages
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Discount below 0%")]
    [DataRow(100.01, DisplayName = "Discount above 100%")]
    public void ApplyDiscount_InvalidDiscount_Throws(double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    // ───────────────────────────────────────────────
    //  FormatPrice – [DynamicData] from a method source
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> FormatPriceCases()
    {
        yield return new object[] { 9.99m, "$", "$9.99" };
        yield return new object[] { 1000m, "$", "$1000.00" };
        yield return new object[] { 49.999m, "€", "€50.00" };
        yield return new object[] { 0m, "£", "£0.00" };
    }

    [TestMethod]
    [DynamicData(nameof(FormatPriceCases), DynamicDataSourceType.Method)]
    public void FormatPrice_ReturnsFormattedString(
        decimal price, string symbol, string expected)
    {
        var result = _calculator.FormatPrice(price, symbol);

        Assert.AreEqual(expected, result);
    }
}

